import Foundation

// From Bezzle/MCP/MCPDefinitions.swift, for Windows: the tools as the assistant is told of them, in
// the Mac's words; those Windows has no way to do yet are left out: importing a website and
// removing a background.

/// The tools as the assistant is told of them: each one's name, what it does, and what it takes.
extension MCPTools {
    func makeDefinitions() -> [Definition] {
        let design = ("design", Self.text("Which design: its name or path. Leave it out for the one in front; one not open is opened."))
        let layers = ("layers", Self.list("Layers by id, or by name (\"Artboard/Name\" when the name is on several). Leave it out for the selection."))
        let layerKinds = ["artboard", "carousel", "rectangle", "ellipse", "line", "text", "path", "group"]
        let newLayer: JSONValue = .object([
            ("type", "object"),
            ("properties", .object([
                ("kind", Self.choice(layerKinds, "What it is. A carousel is an artboard of slides side by side, exported a picture a slide.")),
                ("children", ["type": "array", "items": ["type": "object"],
                              "description": "For artboards and groups: the layers in it, bottom first, each like this one. A new group's layers are placed in its parent's coordinates, and it fits itself round them."]),
            ] + Self.layerProperties)),
            ("required", ["kind"]),
        ])
        let change: JSONValue = .object([
            ("type", "object"),
            ("properties", .object([
                ("layer", Self.text("The layer to change, by id or name.")),
                ("layers", Self.list("Several layers to change the same way, in place of layer.")),
            ] + Self.layerProperties)),
        ])

        return [
            Definition(name: "list_designs", title: "List designs",
                       description: "Lists the designs on Bezzle's home screen, the latest first, and which are open in windows.",
                       properties: [:], readOnly: true, run: { [unowned self] in try self.listDesigns($0) }),
            Definition(name: "create_design", title: "Create a design",
                       description: "Makes a new design in the Bezzle folder and opens it in a tab of its own. Give it a first artboard by preset, carousel format, or width and height; or none, for an empty canvas. Add more with add_layers.",
                       properties: .object([
                           ("name", Self.text("What the design is called; \"Untitled\" otherwise.")),
                           ("preset", Self.text("A first artboard of a preset size: \(Preset.all.map { "\($0.name) (\(Int($0.size.width))×\(Int($0.size.height)))" }.joined(separator: ", ")).")),
                           ("carousel", Self.text("A first artboard that is a carousel of this format: \(Carousel.formats.map(\.name).joined(separator: ", ")).")),
                           ("width", Self.number("A first artboard this wide.")),
                           ("height", Self.number("A first artboard this tall.")),
                       ]), run: { [unowned self] in try await self.createDesign($0) }),
            Definition(name: "open_design", title: "Open a design",
                       description: "Opens a design in a tab of its own, or brings its tab to the front. Opening an Adobe XD, Figma (.fig) or Sketch file brings it in as a new design.",
                       properties: .object([("design", Self.text("Its name, as list_designs gives it, or the path of a .bezzle, .vellum, .xd, .fig, .sketch, .psd or .psb file."))]),
                       required: ["design"], run: { [unowned self] in try await self.openDesign($0) }),
            Definition(name: "close_design", title: "Close a design",
                       description: "Closes a design's tab. It is saved; designs always are.",
                       properties: .object([design]), run: { [unowned self] in try await self.closeDesign($0) }),
            Definition(name: "rename_design", title: "Rename a design",
                       description: "Gives a design a new name, renaming its file.",
                       properties: .object([design, ("name", Self.text("The new name."))]), required: ["name"],
                       run: { [unowned self] in try await self.renameDesign($0) }),
            Definition(name: "duplicate_design", title: "Duplicate a design",
                       description: "Makes a copy of a design beside it, called \"… copy\". The copy is not opened.",
                       properties: .object([("design", Self.text("The design to copy, by name or path."))]), required: ["design"],
                       run: { [unowned self] in try await self.duplicateDesign($0) }),
            Definition(name: "delete_design", title: "Delete a design",
                       description: "Closes a design if it is open and moves it to the Recycle Bin.",
                       properties: .object([("design", Self.text("The design to delete, by name or path."))]), required: ["design"], destructive: true,
                       run: { [unowned self] in try await self.deleteDesign($0) }),
            Definition(name: "get_design", title: "Get a design",
                       description: "What is in a design: its artboards and layers as a tree, bottom first, with ids, kinds, names, positions, sizes, fills and text; and what is selected, the zoom, and what Undo would undo. get_layers has everything about particular layers.",
                       properties: .object([
                           design,
                           ("layer", Self.text("Only this artboard or group and what is in it.")),
                           ("depth", Self.integer("How many levels down to list: 0 for only the artboards. Everything otherwise.")),
                       ]), readOnly: true, run: { [unowned self] in try await self.getDesign($0) }),
            Definition(name: "find_layers", title: "Find layers",
                       description: "Finds layers by part of their name, their kind, or their words.",
                       properties: .object([
                           design,
                           ("name", Self.text("Part of the name, in any case.")),
                           ("kind", Self.choice(Array(layerKinds.filter { $0 != "carousel" }), "Only layers of this kind.")),
                           ("text", Self.text("Text layers whose words have this in them.")),
                           ("within", Self.text("Only inside this artboard or group.")),
                       ]), readOnly: true, run: { [unowned self] in try await self.findLayers($0) }),
            Definition(name: "get_layers", title: "Get layers",
                       description: "Everything about some layers: where they are, fill, border, shadow, corners, font, blur, outline and the rest, in the form update_layers takes.",
                       properties: .object([design, layers, ("children", Self.boolean("With all they hold, for artboards and groups."))]),
                       readOnly: true, run: { [unowned self] in try await self.getLayers($0) }),
            Definition(name: "add_layers", title: "Add layers",
                       description: "Adds layers: artboards on the canvas, and anything else on an artboard, in a group, or loose on the canvas. Nest children to build a whole screen in one call; it is one step of the undo history. A layer not placed with x and y goes in the middle of its parent; a new artboard goes to the right of the others. The new layers are selected.",
                       properties: .object([
                           design,
                           ("parent", Self.text("The artboard or group they go in, or \"canvas\". The selection's artboard, or the one in view, otherwise. Artboards always go on the canvas.")),
                           ("index", Self.integer("Where among the parent's layers, counted from the bottom from 0. On top otherwise.")),
                           ("layers", ["type": "array", "items": newLayer, "description": "The layers to add, bottom first."]),
                       ]), required: ["layers"], run: { [unowned self] in try await self.addLayers($0) }),
            Definition(name: "update_layers", title: "Update layers",
                       description: "Changes layers: any of their properties, each update to one layer or several. All of it is one step of the undo history. Only what is given changes; objects such as border and font are merged into what is there.",
                       properties: .object([
                           design,
                           ("updates", ["type": "array", "items": change, "description": "Each a layer (or layers), and what to change on it. Without layer or layers, it changes the selection."]),
                       ]), required: ["updates"], run: { [unowned self] in try await self.updateLayers($0) }),
            Definition(name: "delete_layers", title: "Delete layers",
                       description: "Deletes layers, with all they hold.",
                       properties: .object([design, layers]), destructive: true, run: { [unowned self] in try await self.deleteLayers($0) }),
            Definition(name: "duplicate_layers", title: "Duplicate layers",
                       description: "Puts a copy of each layer just above it, offset a little; an artboard's copy goes beside it. The copies are selected.",
                       properties: .object([
                           design, layers,
                           ("dx", Self.number("How far right each copy goes; 10 otherwise.")),
                           ("dy", Self.number("How far down; 10 otherwise.")),
                       ]), run: { [unowned self] in try await self.duplicateLayers($0) }),
            Definition(name: "move_layers", title: "Move layers in the list",
                       description: "Moves layers to another artboard or group, or onto the canvas, and to a place among its layers. They keep where they are on the canvas; move them on it with update_layers' x and y.",
                       properties: .object([
                           design, layers,
                           ("parent", Self.text("The artboard or group they go in, or \"canvas\". Their own parent otherwise.")),
                           ("index", Self.integer("Where among its layers, counted from the bottom from 0. On top otherwise.")),
                       ]), run: { [unowned self] in try await self.moveLayers($0) }),
            Definition(name: "group_layers", title: "Group layers",
                       description: "Puts layers on one artboard, or all on the canvas, into a new group, in the artboard or group that holds them all, where the topmost of them was. Groups move and resize as one.",
                       properties: .object([design, layers, ("name", Self.text("The group's name; \"Group 1\" and so on otherwise."))]),
                       run: { [unowned self] in try await self.groupLayers($0) }),
            Definition(name: "ungroup_layers", title: "Ungroup",
                       description: "Takes the layers out of groups, where they are, and takes the groups away.",
                       properties: .object([design, ("layers", Self.list("The groups. Leave it out for the selection."))]),
                       run: { [unowned self] in try await self.ungroupLayers($0) }),
            Definition(name: "mask_layers", title: "Mask layers",
                       description: "Puts layers inside a shape, as a shape holds a picture: they are cut off at its outline, its fill and shadow lie under them and its border over them. The result is a group with \"mask\": true whose first layer is the shape; it is as big as the shape. Move what it holds within it with update_layers to change what shows. Give shape for the rectangle, ellipse or path that holds (or a mask, to add to it); otherwise it is a mask among the layers, or the topmost shape without a picture, or the topmost shape.",
                       properties: .object([
                           design, layers,
                           ("shape", Self.text("The shape, or mask, that holds the others. Picked from the layers otherwise.")),
                       ]), run: { [unowned self] in try await self.maskLayers($0) }),
            Definition(name: "release_mask", title: "Release mask",
                       description: "Takes masks apart: the shape and what it held lie where they are, the shape under them, shown whole. Or, given layers inside a mask, takes just those out of it, just above it.",
                       properties: .object([design, ("layers", Self.list("Masks to take apart, or layers inside one to take out. Leave it out for the selection."))]),
                       run: { [unowned self] in try await self.releaseMask($0) }),
            Definition(name: "arrange_layers", title: "Arrange layers",
                       description: "Brings layers to the front or forward, or sends them backward or to the back, among the layers they lie with.",
                       properties: .object([design, layers, ("order", Self.choice(["front", "forward", "backward", "back"], "Where to."))]),
                       required: ["order"], run: { [unowned self] in try await self.arrangeLayers($0) }),
            Definition(name: "align_layers", title: "Align layers",
                       description: "Lines layers up by an edge or their middles. A layer on its own lines up with its artboard.",
                       properties: .object([design, layers, ("edge", Self.choice(["left", "center", "right", "top", "middle", "bottom"], "center is across, middle is up and down."))]),
                       required: ["edge"], run: { [unowned self] in try await self.alignLayers($0) }),
            Definition(name: "distribute_layers", title: "Distribute layers",
                       description: "Spaces three layers or more evenly between the outermost two.",
                       properties: .object([design, layers, ("direction", Self.choice(["horizontal", "vertical"], "Across or down."))]),
                       required: ["direction"], run: { [unowned self] in try await self.distributeLayers($0) }),
            Definition(name: "flip_layers", title: "Flip layers",
                       description: "Mirrors layers where they are: one about its own middle, several about the middle of them all. Words still read forwards.",
                       properties: .object([design, layers, ("direction", Self.choice(["horizontal", "vertical"], "Left to right, or top to bottom."))]),
                       required: ["direction"], run: { [unowned self] in try await self.flipLayers($0) }),
            Definition(name: "combine_shapes", title: "Combine shapes",
                       description: "Makes two or more rectangles, ellipses and paths one path, styled as the one at the back. union: all of them. subtract: the back one less those in front. intersect: only where all overlap. exclude: only where an odd number overlap.",
                       properties: .object([design, layers, ("operation", Self.choice(["union", "subtract", "intersect", "exclude"], "How."))]),
                       required: ["operation"], run: { [unowned self] in try await self.combineShapes($0) }),
            Definition(name: "convert_to_path", title: "Convert to path",
                       description: "Makes rectangles, ellipses and lines paths, whose outline can then be given as SVG path data. Each keeps its id. Texts stay texts in Bezzle for Windows: it cannot outline letters yet.",
                       properties: .object([design, layers]), run: { [unowned self] in try await self.convertToPath($0) }),
            Definition(name: "place_image", title: "Place a picture",
                       description: "Puts a picture file into the design: as a new rectangle filled with it, at its own size unless that is too big; or into an existing rectangle, ellipse or path's fill, the letters of a text, or a layer's first border. The file is copied into the design.",
                       properties: .object([
                           design,
                           ("file", Self.text("The picture's path: PNG, JPEG, GIF, WebP, BMP…")),
                           ("layer", Self.text("A rectangle, ellipse, path or text to fill with it, in place of a new layer; or with into: border, a shape or line whose border it paints.")),
                           ("into", Self.choice(["fill", "border"], "With layer: fill (the usual) or its first border, which comes on if it was off.")),
                           ("mode", Self.choice(["cover", "fit", "stretch"], "cover fills the layer and crops what overflows (the usual); fit shows it whole; stretch squeezes it to the layer.")),
                           ("parent", Self.text("For a new layer: the artboard or group it goes in, or \"canvas\".")),
                           ("name", Self.text("For a new layer: its name; the file's otherwise.")),
                           ("x", Self.number("For a new layer: its left, in the parent. In the middle otherwise.")),
                           ("y", Self.number("For a new layer: its top.")),
                           ("width", Self.number("For a new layer: its width. Given one side only, the other keeps the picture's proportions.")),
                           ("height", Self.number("For a new layer: its height.")),
                       ]), required: ["file"], run: { [unowned self] in try await self.placeImage($0) }),
            Definition(name: "develop_photo", title: "Develop a photo",
                       description: "Develops the photos filling layers, as a photo editor such as Lightroom does: their light (exposure, contrast, highlights, shadows, whites, blacks), colour (temperature, tint, vibrance, saturation, and each colour on its own) and detail (clarity, texture, dehaze, sharpness). Only what is given changes; 0 takes a setting away. The photo itself is kept, so reset brings it back as taken. get_layers shows a photo's settings as fill.image.develop; render shows the result.",
                       properties: .object(Self.developDefinitionProperties), run: { [unowned self] in try await self.developPhoto($0) }),
            Definition(name: "repeat_grid", title: "Make or change a repeat grid",
                       description: "Makes layers a repeat grid, or changes one: a layer (several are grouped first) repeated in columns across and rows down, the same gap apart. Every cell is a copy of the first: change any layer in any cell (update_layers, add_layers into a cell's group, delete_layers) and it changes in all of them, but for words and pictures, which each cell holds of its own (fill_repeat_grid). New cells continue a series of numbers, or repeat what the cells before them hold. update_layers' rotation turns a grid as one, and flip_layers mirrors it as one. get_layers on the grid lists its first cell and every cell's words.",
                       properties: .object([
                           design,
                           ("layers", Self.list("The layers to repeat, or a repeat grid to change. Leave it out for the selection.")),
                           ("columns", Self.integer("How many columns, 1 to \(RepeatGrid.counts.upperBound).")),
                           ("rows", Self.integer("How many rows, 1 to \(RepeatGrid.counts.upperBound).")),
                           ("column_gap", Self.number("The space between columns; below zero they overlap. A new grid's suits its cell otherwise.")),
                           ("row_gap", Self.number("The space between rows.")),
                           ("name", Self.text("A new grid's name; \"Repeat Grid 1\" and so on otherwise.")),
                           ("ungroup", Self.boolean("true makes a grid a plain group of its cells, each a layer of its own from then on.")),
                       ]), run: { [unowned self] in try await self.repeatGrid($0) }),
            Definition(name: "fill_repeat_grid", title: "Fill a repeat grid's cells",
                       description: "Gives each cell of a repeat grid its own words or pictures, in reading order (left to right, then down), round again when there are fewer than cells. Give layer (a text or shape in any cell, or the grid itself for data) and one of: values (words), sample (made-up content), pictures (files or folders), or data (CSV with a heading row, each column going to the text layer of the same name; or plain lines).",
                       properties: .object([
                           design,
                           ("layer", Self.text("A text layer or shape in one of the grid's cells, by id or name; or the grid.")),
                           ("values", Self.list("The words, one a cell.")),
                           ("sample", Self.choice(Self.sampleNames, "Made-up content of this kind; numbers keep the words around a number already there, so \"Step 1\" goes on \"Step 2\".")),
                           ("pictures", Self.list("Picture files, or folders of them, one a cell; for a rectangle, ellipse or path.")),
                           ("data", Self.text("CSV or tab-separated text with a heading row, or lines: fills the grid's text layers.")),
                       ]), required: ["layer"], run: { [unowned self] in try await self.fillRepeatGrid($0) }),
            Definition(name: "layout_grid", title: "Lay out an artboard on a grid",
                       description: "Gives an artboard a layout grid, or changes or removes it: columns side by side across it and rows down it, each `count` of them stretching between `margin` at either end with `gutter` between them, and baselines `baseline` apart for text to sit on. It is drawn over the artboard while designing and never exported; layers moved, resized or drawn on the artboard catch on the columns' and rows' edges, and text on the baselines by its first line. On a carousel it repeats on every slide. suggested gives the grid that suits the artboard's size (4 columns on a phone, 8 on a tablet or post, 12 on a desktop). A part not given stays as it is; a count of 0 removes it. get_layers on the artboard shows layoutGrid.",
                       properties: .object([
                           design,
                           ("layer", Self.text("The artboard, or a layer on it, by id or name. Leave it out for the selection's artboard, or the one in sight.")),
                           ("suggested", Self.boolean("Starts from the grid that suits the artboard's size.")),
                           ("columns", Self.integer("How many columns, 1 to \(LayoutGrid.Track.counts.upperBound); 0 removes them.")),
                           ("column_gutter", Self.number("The space between columns.")),
                           ("column_margin", Self.number("The space before the first column and after the last.")),
                           ("rows", Self.integer("How many rows, 1 to \(LayoutGrid.Track.counts.upperBound); 0 removes them.")),
                           ("row_gutter", Self.number("The space between rows.")),
                           ("row_margin", Self.number("The space above the first row and below the last.")),
                           ("baseline", Self.number("How far apart the baselines are, such as 4 or 8; 0 removes them.")),
                           ("baseline_offset", Self.number("How far below the top the first baseline is.")),
                           ("remove", Self.boolean("Takes the whole grid away.")),
                       ]), run: { [unowned self] in try await self.layoutGrid($0) }),
            Definition(name: "guides", title: "Put guides on an artboard",
                       description: "Adds guides to an artboard, or removes them: lines to line layers up with, as if pulled out of the rulers, which layers catch on as they are moved, resized or drawn. A vertical guide runs down the artboard at a distance across it, a horizontal one across it at a distance down. Each keeps that distance from the edge it is measured from (from: start, middle or end; the nearer edge when left out) as the artboard changes size, so a margin guide stays a margin. Drawn while designing, never exported. get_layers on the artboard lists its guides with their ids.",
                       properties: .object([
                           design,
                           ("layer", Self.text("The artboard, or a layer on it, by id or name. Leave it out for the selection's artboard, or the one in sight.")),
                           ("add", ["type": "array", "items": ["type": "object"],
                                    "description": "Guides to add, each {direction: \"vertical\" or \"horizontal\", at: distance, from: \"start\", \"middle\" or \"end\"}. start is the left or top edge."]),
                           ("remove", Self.list("Ids of guides to take away, or [\"all\"].")),
                       ]), run: { [unowned self] in try await self.guides($0) }),
            Definition(name: "notes", title: "Read, write and answer notes",
                       description: "Notes are what people write in a design's margins about a layer or an artboard, at a spot on it or round a part of it circled in pencil, and their answers, as threads. Shared designs carry everyone's. With nothing but design, lists the threads, closed (ticked off) ones marked, each with its answers. write starts a thread about layer (at x, y from 0 to 1 across and down it; the middle otherwise), or at x, y on the canvas; with area instead, about the part circled. answer with thread adds an answer. close or reopen take thread ids; a closed thread leaves the margin. move puts a thread's spot elsewhere. remove takes note ids, a thread's id taking its answers too. show opens a thread on screen, the view flying to it. Your notes are signed Claude.",
                       properties: .object([
                           design,
                           ("write", Self.text("Starts a thread with these words.")),
                           ("layer", Self.text("With write: the layer or artboard it is about, by id or name.")),
                           ("x", Self.number("With write: across the layer, 0 to 1; or on the canvas, without layer.")),
                           ("y", Self.number("With write: down the layer, 0 to 1; or on the canvas, without layer.")),
                           ("area", ["type": "object", "description": "With write or move: the part circled, {x, y, width, height}, on the canvas; it goes with the layer it is round as that moves."]),
                           ("answer", Self.text("Answers thread with these words.")),
                           ("thread", Self.text("With answer or move: the id of the note that starts the thread.")),
                           ("move", ["type": "object", "description": "With thread: where its spot goes now, {x, y} on the canvas; it is about whatever is there. With area, the loop moves round that instead."]),
                           ("show", Self.text("The id of a thread to open on screen.")),
                           ("close", Self.list("Ids of threads talked out.")),
                           ("reopen", Self.list("Ids of closed threads to open again.")),
                           ("remove", Self.list("Ids of notes to take away.")),
                       ]), run: { [unowned self] in try await self.notes($0) }),
            Definition(name: "versions", title: "List, name or go back to versions",
                       description: "A design keeps versions of itself as it is worked on, and named ones for good. With nothing but design, lists them, newest first. name keeps the design as it is now as a version with that name. go_back_to with a version's id makes the design what it was then: a change like any other, which undo takes back, with the design as it was just before kept as a named version first, and its notes left as they are.",
                       properties: .object([
                           design,
                           ("name", Self.text("Keeps the design as it is now as a version called this.")),
                           ("go_back_to", Self.text("The id of a version to go back to.")),
                           ("show", Self.text("Shows a version on the canvas for the person to see, with the ruler of time out: its id, \"now\", or \"none\" to put the ruler away. It changes nothing.")),
                       ]), run: { [unowned self] in try await self.versions($0) }),
            Definition(name: "styles", title: "List, name, use or change styles",
                       description: "Styles are looks with names: colours (a fill's, a text's, a border's), text styles (font, size, spacing), shadows and corners. A layer using a style looks as it does, and the style is the same on every layer: change it here, or change that look on any layer that uses it with update_layers, and every layer using it changes. With nothing but design, lists the styles (with their dark looks), how many layers use each, and the looks several layers share without a name. appearance shows an artboard dark or light. name with layer (and place, all_alike) names a layer's look. style with layers gives them the style; with rename, color, type, shadow or corners, changes it; with remove, takes it away, leaving its layers as they look. unname with layers lets them go of their names.",
                       properties: .object([
                           design,
                           ("name", Self.text("Makes a style of the look layer has at place, called this (\"\" for a name that says what it is).")),
                           ("layer", Self.text("With name: the layer whose look is named, by id or name.")),
                           ("place", Self.text("Where on a layer: fill, border, shadow, text or corners, with a number for the second and on (\"fill 2\"). Left out, the first that can be named.")),
                           ("all_alike", Self.boolean("With name: every other layer with the same look, unnamed, takes the new style too.")),
                           ("style", Self.text("A style, by id or name.")),
                           layers,
                           ("use", Self.boolean("With style: gives the selection the style, when layers is left out.")),
                           ("rename", Self.text("With style: its new name.")),
                           ("color", Self.text("With a colour style: its new colour, \"#RRGGBB\" or \"#RRGGBBAA\".")),
                           ("type", ["type": "object", "description": "With a text style: any of family, face, size, line_spacing (null for the font's own), letter_spacing (thousandths of the size), paragraph_spacing, case (upper, lower, title, smallCaps, none), underline, strikethrough."]),
                           ("shadow", ["type": "object", "description": "With a shadow style: any of x, y, blur, spread, color, inset."]),
                           ("corners", Self.number("With a corners style: the radius.")),
                           ("smoothing", Self.number("With corners: how smoothly they run into the sides, 0 to 1 (0.6 is the iOS squircle).")),
                           ("remove", Self.boolean("With style: takes it away. Its layers keep their looks.")),
                           ("unname", Self.boolean("With layers (and place): they keep their looks without a style's name.")),
                           ("appearance", Self.choice(["dark", "light", "none"], "With layer, an artboard: shows it dark, every style on it in its dark look, or light again (none: light, without the switch to dark). Made dark, its colours without a name are named first, so all of it turns dark.")),
                           ("dark_color", Self.text("With a colour style: its colour in the dark, \"#RRGGBB\".")),
                           ("dark_auto", Self.boolean("With style: its dark look is made from its light one by itself again.")),
                       ]), run: { [unowned self] in try await self.styles($0) }),
            Definition(name: "deck", title: "Make or change a deck",
                       description: "A deck is one artboard that is many posts lying one behind another, such as social posts in the same design: only the post in front shows, and each is exported as a file of its own. Every post is a copy of one design: a change to how a layer looks in any post (update_layers, add_layers onto it, delete_layers) is made in every post, while each post's words and pictures are its own. Give layer (an artboard, or a layer on one) and any of: add (that many new posts, copies of the post in front or of `after`; an artboard that is no deck becomes one), values with text_layer (words, one a post from post `from` on, adding posts as needed), pictures with shape_layer (the same for pictures), remove, move, show (bring a post to the front on screen), post (list that post's layers and ids), unstack. Posts are counted from 1. get_layers on a deck lists its first post and every post's words.",
                       properties: .object([
                           design,
