            Definition(name: "list_fonts", title: "List fonts",
                       description: "Lists the font families Bezzle has, or the faces of one, as font.family and font.face take them.",
                       properties: .object([
                           ("family", Self.text("A family whose faces to list.")),
                           ("search", Self.text("Only families whose name has this in it.")),
                       ]), readOnly: true, run: { [unowned self] in try self.listFonts($0) }),
            Definition(name: "style_text", title: "Style words in a text",
                       description: "Styles some of a text layer's letters, leaving the rest as they are: a word in bold or another colour, a struck-through price, a paragraph made an item of a list. Give layer, which letters (find: words to style, every time they come or only the occurrence-th; or start and length, counted in characters; neither styles every letter), and any of family, face, size, color, underline, strikethrough, tracking, list (bullet, number or none, for the paragraphs those letters are in). What is not given stays as it is. get_layers shows the result as spans.",
                       properties: .object([
