                           ("start", Self.integer("Instead of find: the first letter to style, counted from 0.")),
                           ("length", Self.integer("With start: how many letters.")),
                           ("family", Self.text("A font family as list_fonts gives it.")),
                           ("face", Self.text("\"Bold\", \"Italic\", \"Semibold\"…: one of the family's faces.")),
                           ("size", Self.number("In points.")),
                           ("color", Self.text("\"#RRGGBB\" or \"#RRGGBBAA\".")),
                           ("underline", Self.boolean("Underlined.")),
                           ("strikethrough", Self.boolean("Struck through.")),
                           ("tracking", Self.number("Space between letters, in thousandths of the size.")),
                           ("list", Self.choice(["bullet", "number", "none"], "Makes the paragraphs the letters are in items of a list, or no longer.")),
