                       ]), required: ["find"], run: { [unowned self] in try await self.replaceText($0) }),
            Definition(name: "check_spelling", title: "Check spelling",
                       description: "Lists the misspelt words in the design's text layers, each in the language its text is written in, with the layer, where in its words it is, and how it might be spelt. Correct one with replace_text, or update_layers.",
                       properties: .object([
